import {DIRS,Random,newGame,move,undo,redo,choose,empty,status,remaining,snapshot,slide,spawn,canMove,powers,swapCost,STAGES,ABILITIES,dailySeed,clone} from './engine.js';
import {Storage,sessionKey} from './storage.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={classic:'经典 2048',daily:'每日同局',puzzle:'谜题剧场',sprint:'六十步冲刺',expedition:'能力远征',rescue:'败局重生'},kickers={classic:'THE ORIGINAL',daily:'A NEW DAY, A NEW GAME',puzzle:'LESS IS MORE',sprint:'MAKE EVERY MOVE COUNT',expedition:'BUILD YOUR OWN WAY',rescue:'ANOTHER POSSIBILITY'},arrows={left:'←',up:'↑',right:'→',down:'↓',freeze:'❄'},directions={left:'向左',up:'向上',right:'向右',down:'向下',freeze:'使用凝时'};
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const freshSeed=()=>{const a=new Uint32Array(2);crypto.getRandomValues(a);return (BigInt(a[0])<<21n)+BigInt(a[1]&0x1fffff);};
let game,levels=[],practice=[],busy=false,queued=[],auto=false,autoTimer=0,worker=null,requestID=0,pendingReject=null,toastTimer=0,swapSelection=null,swapping=false,analysis=null,version=0,activeAnimations=[],lastDialogFocus=null,audioContext=null,saveWarning=false,remoteLock=false;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const store=new Storage(error=>{if(error){$('#save-state').textContent=error;$('.device-note').classList.add('save-error');if(!saveWarning){toast(error);saveWarning=true;}}else{$('#save-state').textContent='自动保存在此设备';$('.device-note').classList.remove('save-error');saveWarning=false;}});
$('.cells').innerHTML='<div class="cell"></div>'.repeat(16);
$$('.app button').forEach(b=>b.disabled=true);
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3800);}
function motion(){return store.meta.settings.motion&&!reduced.matches;}
function announce(message){$('#announcement').textContent=message;}
function applySettings(){document.body.classList.toggle('dark',store.meta.settings.theme==='dark'||(store.meta.settings.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches));}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applySettings);
function sound(gain){if(!store.meta.settings.sound)return;try{audioContext||=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume().catch(()=>{});const osc=audioContext.createOscillator(),amp=audioContext.createGain(),t=audioContext.currentTime;osc.type='sine';osc.frequency.setValueAtTime(gain?440+Math.min(6,Math.log2(gain))*35:250,t);amp.gain.setValueAtTime(.0001,t);amp.gain.exponentialRampToValueAtTime(.032,t+.008);amp.gain.exponentialRampToValueAtTime(.0001,t+.105);osc.connect(amp).connect(audioContext.destination);osc.start();osc.stop(t+.12);}catch{}}
const bestKey=()=>`${sessionKey(game)}:${game.assisted?'assisted':'manual'}`;
function persist(){if(!game||remoteLock)return;store.meta.best[bestKey()]=Math.max(store.meta.best[bestKey()]||0,game.score);const key=sessionKey(game);store.save(game).then(()=>channel?.postMessage({source:tabID,key}));}
function tile(value,index){const el=document.createElement('div');el.className=`tile${value>=1024?' long':''}${value>=100000?' very-long':''}${index===swapSelection?' selected':''}`;el.dataset.value=value;el.dataset.index=index;el.dataset.high=value>=2048;el.textContent=value;el.style.left=`calc(${index%4} * (100% + var(--gap)) / 4)`;el.style.top=`calc(${Math.floor(index/4)} * (100% + var(--gap)) / 4)`;return el;}
function renderTiles(pop=null){const layer=$('.tiles');layer.replaceChildren();game.board.forEach((v,i)=>{if(v){const el=tile(v,i);layer.append(el);if(pop&&motion()){if(pop.merges.includes(i))el.animate([{transform:'scale(1)'},{transform:'scale(1.085)',offset:.45},{transform:'scale(1)'}],{duration:185,easing:'cubic-bezier(.2,.7,.3,1)'});else if(pop.spawn===i)el.animate([{transform:'scale(.65)',opacity:0},{transform:'scale(1)',opacity:1}],{duration:150,easing:'cubic-bezier(.2,.7,.3,1)'});}}});$('#board').setAttribute('aria-label',`${names[game.mode]}棋盘，${game.board.map(v=>v||'空').join('，')}。可滑动或使用下方方向按钮。`);}
function render(){
  $('#mode-title').textContent=names[game.mode];$('#mode-kicker').textContent=kickers[game.mode];$('#score').textContent=game.score.toLocaleString();$('#best').textContent=Math.max(store.meta.best[bestKey()]||0,game.score).toLocaleString();$('#best-label').textContent=game.assisted?'辅助最佳':'个人最佳';$('#max-tile').textContent=Math.max(...game.board);$('#empty-count').textContent=empty(game.board);$('#detail-label').textContent=Number.isFinite(remaining(game))?'剩余步数':'移动次数';$('#detail').textContent=Number.isFinite(remaining(game))?remaining(game):game.moves;
  $('#undo').disabled=!game.history.length||busy;$('#hint').disabled=status(game)!=='play'||busy;$('#auto').disabled=status(game)!=='play'||busy&&!auto;$('#auto').classList.toggle('active',auto);$('#auto span').textContent=auto?'暂停':'自动玩';$('#auto').setAttribute('aria-pressed',String(auto));
  $('#score-label').textContent=game.mode==='expedition'?`第 ${game.extra.stage+1} 关 · ${STAGES[game.extra.stage][0]}`:game.mode==='daily'?game.extra.date:'本局得分';
  const note={classic:['一局之外，还有惊喜。','搭配能力，走得更远。<br>重返败局，找到另一种可能。'],daily:['今天，属于这一局。','相同日期有相同开局与落子规则。<br>每天一题，按自己的节奏来。'],puzzle:[game.extra.level?.title||'谜题剧场',`在 ${game.extra.level?.limit} 步内合成 ${game.extra.level?.target}。<br>最短路线 ${game.extra.level?.par} 步。`],sprint:['让每一步都值得。','只有六十次有效移动。<br>在步数用完之前，尽可能多得分。'],expedition:['选择，改变下一局。','九种能力，两级进化。<br>带着自己的组合，走过六个关卡。'],rescue:['如果，那一步不同。','重返一个真实的岔路口。<br>六步之内，重新打开三格空间。']}[game.mode];
  $('#note-title').textContent=note[0];$('#note-copy').innerHTML=note[1];$('#gesture-tip').textContent=swapping?'依次轻点两枚不同数字，交换位置。':game.mode==='puzzle'?`${game.extra.level.title} · ${game.extra.level.limit} 步内合成 ${game.extra.level.target}`:game.mode==='rescue'?`${remaining(game)} 步之内，打开 ${game.extra.goal} 格空间。`:game.mode==='expedition'?`本关进度 ${game.score-game.extra.stage_score} / ${STAGES[game.extra.stage][1]} 分`:'轻轻滑动，让相同的数字相遇。';
  $('#power-bar').hidden=game.mode!=='expedition';if(game.mode==='expedition'){$('#power-bar').innerHTML=`<span>ϟ ${game.extra.energy} / 12${game.extra.freeze?` · 凝时 ${game.extra.freeze}`:''}</span><button id="freeze-power" ${!powers(game).includes('freeze')?'disabled':''}>凝时 · 5${game.extra.cooldown?` (${game.extra.cooldown})`:''}</button><button id="swap-power" ${!powers(game).some(p=>p.startsWith('swap:'))?'disabled':''}>${swapping?'取消交换':`交换 · ${swapCost(game.extra)}`}</button><button id="perks">能力</button>`;$('#freeze-power').onclick=()=>input('freeze');$('#swap-power').onclick=()=>{stopAuto();swapping=!swapping;swapSelection=null;renderTiles();render();};$('#perks').onclick=showPerks;}
  renderOverlay();if(!analysis)resetInsight();
}
function renderOverlay(){const phase=status(game),el=$('#board-message');el.hidden=phase==='play'||busy;if(phase==='play'||busy)return;
  let title,copy,buttons;if(phase==='draft'||phase==='clear'){title=phase==='draft'?'选择你的第一种能力':'这一关，漂亮。';copy=phase==='draft'?'三选一，开始属于你的远征。':`第 ${game.extra.stage+1} 关完成。保留棋盘，带着新的能力继续。`;buttons='<button class="primary" id="draft-button">选择能力 ↗</button>';}
  else if(phase==='won'){title=game.mode==='expedition'?'远征完成。':game.mode==='rescue'?'转机，找到了。':'恰到好处。';copy=game.mode==='expedition'?'六个关卡，你已走过。':game.mode==='rescue'?`${game.moves} 步打开 ${empty(game.board)} 格空间。`:`用 ${game.moves} 步合成了 ${Math.max(...game.board)}。`;buttons=game.mode==='puzzle'?'<button class="primary" id="next-level">下一题 ↗</button><button class="secondary" id="retry">再试一次</button>':game.mode==='rescue'?'<button class="primary" id="review-rescue">看看两条路</button><button class="secondary" id="rescue-home">更多转机</button>':'<button class="primary" id="retry">再来一局</button>';}
  else{title=game.mode==='sprint'&&remaining(game)===0?'六十步，刚刚好。':game.mode==='puzzle'||game.mode==='rescue'?'再换个思路。':'这一局，先到这里。';copy=game.mode==='puzzle'||game.mode==='rescue'?'重来时落子不变，可以尝试另一条路。':`${game.score.toLocaleString()} 分 · 最大方块 ${Math.max(...game.board)}`;buttons='<button class="primary" id="retry">再来一次</button>';if(['classic','daily','sprint'].includes(game.mode)&&!canMove(game.board))buttons+='<button class="secondary" id="extract-rescue">寻找转机</button>';else if(game.mode==='rescue')buttons+='<button class="secondary" id="review-rescue">复盘路线</button>';}
  el.innerHTML=`<span class="pill">${phase==='draft'||phase==='clear'?'CHOOSE YOUR WAY':game.assisted?'辅助探索':'LUMINA MOMENT'}</span><h2>${title}</h2><p>${copy}</p><div class="button-row">${buttons}</div>`;
  if($('#draft-button'))$('#draft-button').onclick=showDraft;if($('#retry'))$('#retry').onclick=restart;if($('#next-level'))$('#next-level').onclick=()=>game.extra.level.id<levels.length-1?switchMode('puzzle',levels[game.extra.level.id+1],true):showLevels();if($('#extract-rescue'))$('#extract-rescue').onclick=extractChallenge;if($('#review-rescue'))$('#review-rescue').onclick=()=>showReview('mine');if($('#rescue-home'))$('#rescue-home').onclick=showRescues;
}
function resetInsight(){$('#analysis').hidden=true;$('#insight-title').textContent=game.mode==='expedition'?'让能力彼此呼应。':game.mode==='rescue'?'每一条路，都可以重走。':'慢一点，也很好。';$('#insight-copy').textContent=game.mode==='expedition'?'合并积攒能量。拥挤时试试凝时，也可以交换两枚方块。':game.mode==='rescue'?'这里的落子与原局一致。先自己尝试，再把你的路线与参考路线对照。':'留一点空间，等待下一次相遇。需要时，点一下提示，让助手想一想。';}
function showAnalysis(result){analysis=result;const d=result.direction;$('#insight-title').textContent=d?`${arrows[d]||'⇄'} ${directions[d]||'交换方块'}`:result.complete===false?'还需要多一点时间。':'当前没有达标路线。';
  $('#insight-copy').textContent=result.kind==='exact'?(d?`已验证 ${result.solution.length} 步可以达成目标。` :result.complete===false?'搜索时间已用完，暂时没有找到验证路线。':'在余下步数内，所有路线都未能达成目标。可以撤销或重试。'):d==='freeze'?'暂停落子，为拥挤的棋盘争取合并空间。':d?.startsWith('swap:')?'先整理两枚方块的位置，再继续合并。':game.mode==='expedition'?'结合你的能力、能量和落子概率，寻找更有余地的一步。':'同时考虑空格、数字排列和后续落子概率。建议来自搜索估值。';
  $('#analysis').hidden=false;const vals=result.values?.filter(([key])=>DIRS.includes(key))||[],min=Math.min(...vals.map(v=>v[1])),max=Math.max(...vals.map(v=>v[1]));$('#analysis').innerHTML=vals.map(([key,v],i)=>`<div class="analysis-row ${i===0?'best':''}"><span>${arrows[key]}</span><i><b style="width:${max===min?100:20+80*(v-min)/(max-min)}%"></b></i><small>${i===0?'优先':`备选 ${i}`}</small></div>`).join('')+`<p class="analysis-caption">${result.kind==='exact'?'精确路线搜索':'Expectimax · 概率搜索'}<br>${result.depth} 层 · ${result.nodes.toLocaleString()} 节点 · ${result.ms} ms${result.kind==='expectimax'?' · 排序不代表胜率':''}</p>`;
}
function cancelSearch(){requestID++;if(worker&&pendingReject){worker.terminate();worker=null;}pendingReject?.(new DOMException('Cancelled','AbortError'));pendingReject=null;$('#thinking-dot').hidden=true;}
function stopAuto(){auto=false;clearTimeout(autoTimer);cancelSearch();if(game){$('#auto').classList.remove('active');$('#auto span').textContent='自动玩';$('#auto').setAttribute('aria-pressed','false');}}
function compute(task='solve'){
  cancelSearch();const id=++requestID,copy={...snapshot(game),id:game.id,mode:game.mode};if(task==='extract')copy.history=clone(game.history.slice(-10));
  $('#thinking-dot').hidden=false;return new Promise((resolve,reject)=>{pendingReject=reject;worker||=new Worker(new URL('./ai-worker.js',import.meta.url),{type:'module'});const timeout=setTimeout(()=>{if(id!==requestID)return;cancelSearch();reject(new Error('这次思考超时了，请再试一次。'));},8000);worker.onmessage=({data})=>{if(data.id!==requestID)return;clearTimeout(timeout);pendingReject=null;$('#thinking-dot').hidden=true;data.error?reject(new Error(data.error)):resolve(data.result);};worker.onerror=()=>{clearTimeout(timeout);worker?.terminate();worker=null;pendingReject=null;cancelSearch();reject(new Error('智能助手暂时无法启动，仍可手动游玩。'));};worker.postMessage({id,task,game:copy,budget:task==='extract'?2800:['puzzle','rescue'].includes(game.mode)?2200:({quick:75,balanced:180,deep:600}[store.meta.settings.strength]||180)});});
}
async function hint(){if(busy||status(game)!=='play')return;stopAuto();game.assisted=true;persist();render();const v=version;try{const result=await compute();if(v!==version)return;showAnalysis(result);announce(result.direction?`建议${directions[result.direction]||'交换方块'}`:$('#insight-copy').textContent);}catch(e){if(e.name!=='AbortError')toast(e.message);}}
async function autoStep(){if(!auto||busy||document.hidden||$('#dialog').open||status(game)!=='play')return;const v=version;try{const result=await compute();if(!auto||v!==version)return;showAnalysis(result);if(!result.direction){stopAuto();render();return;}await play(result.direction,true);if(auto&&status(game)==='play')autoTimer=setTimeout(autoStep,store.meta.settings.pace==='quick'?75:280);else{stopAuto();render();}}catch(e){if(e.name!=='AbortError'){stopAuto();render();toast(e.message);}}}
function toggleAuto(){if(auto){stopAuto();render();return;}if(busy||status(game)!=='play')return;swapping=false;swapSelection=null;game.assisted=true;auto=true;persist();render();autoStep();}
async function animate(result){if(!motion()){renderTiles();return;}const layer=$('.tiles'),width=layer.clientWidth,gap=parseFloat(getComputedStyle($('.cells')).columnGap),step=(width+gap)/4;layer.replaceChildren();
  activeAnimations=result.tracks.map(t=>{const el=tile(t.value,t.source);layer.append(el);return el.animate([{transform:'translate(0,0)'},{transform:`translate(${(t.target%4-t.source%4)*step}px,${(Math.floor(t.target/4)-Math.floor(t.source/4))*step}px)`}],{duration:145,easing:'cubic-bezier(.2,.72,.22,1)',fill:'forwards'});});await Promise.allSettled(activeAnimations.map(a=>a.finished));activeAnimations=[];renderTiles(result);
}
function recordCompletion(){const phase=status(game);if(!['won','lost'].includes(phase))return;stopAuto();
  if(game.mode==='puzzle'&&phase==='won'){const stars=game.assisted?1:game.undos||game.moves>game.extra.level.par?2:3;store.meta.stars[game.extra.level.id]=Math.max(store.meta.stars[game.extra.level.id]||0,stars);}
  const row={id:game.id,mode:game.mode,score:game.score,moves:game.moves,tile:Math.max(...game.board),assisted:game.assisted,date:new Date().toISOString(),won:phase==='won',cleared:game.extra.cleared||0};
  const old=store.meta.records.find(r=>r.id===row.id);if(!old||row.score>=old.score)store.meta.records=[row,...store.meta.records.filter(r=>r.id!==row.id)].slice(0,60);
  announce(`${phase==='won'?'挑战成功':'本局结束'}，${game.score} 分。`);
}
async function play(d,assisted=false){if(busy||remoteLock||status(game)!=='play')return false;const result=move(game,d,assisted);if(!result){if(!assisted){toast('这个方向暂时不能移动');announce('这个方向暂时不能移动');}return false;}version++;busy=true;analysis=null;swapping=false;swapSelection=null;render();persist();sound(result.gain);if(result.gain){$('#gain').textContent=`+${result.gain}`;$('#gain').animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-14px)'}],{duration:700,fill:'forwards'});}await animate(result);busy=false;recordCompletion();persist();render();if(!auto)announce(`${game.score} 分，最大方块 ${Math.max(...game.board)}，剩余 ${empty(game.board)} 个空格。`);if(queued.length&&status(game)==='play'&&!$('#dialog').open){const next=queued.shift();play(next);}else queued=[];return true;}
function input(d){if(!game||$('#dialog').open||remoteLock)return;stopAuto();if(busy){if(queued.length<2)queued.push(d);return;}play(d);}
async function settle(){queued=[];stopAuto();if(activeAnimations.length)activeAnimations.forEach(a=>{try{a.finish();}catch{}});while(busy)await new Promise(r=>setTimeout(r,10));}
async function openDialog(html,kicker='LUMINA ATELIER'){await settle();swapping=false;swapSelection=null;renderTiles();lastDialogFocus=document.activeElement;$('#dialog-kicker').textContent=kicker;$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0;$('#close-dialog').focus();}
function closeDialog(){$('#dialog').close();lastDialogFocus?.focus?.();}
$('#close-dialog').onclick=closeDialog;$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
async function switchMode(mode,data=null,fresh=false){await settle();persist();const key=mode==='daily'?`daily:${localDate()}`:mode;
  if(!fresh&&store.sessions[key])game=clone(store.sessions[key]);else if(mode==='daily')game=newGame(mode,await dailySeed(localDate()),localDate());else if(mode==='puzzle'){const level=data||levels[0];game=newGame(mode,level.seed,level);}else if(mode==='rescue'){if(!data)return showRescues();game=newGame(mode,0,data);}else game=newGame(mode,freshSeed());
  version++;analysis=null;swapSelection=null;swapping=false;$('#gain').textContent='';closeDialog();renderTiles();render();persist();announce(`${names[game.mode]}，${game.score} 分。`);$('#board').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});
}
async function showModes(){await openDialog(`<h2 class="dialog-title">今天，想怎么玩？</h2><p class="dialog-intro">从熟悉的一局开始，再发现一点不同。</p><div class="mode-grid"><button class="mode-card classic" data-mode="classic"><h3>经典 2048</h3><p>纯粹的合并，熟悉的乐趣。<br>${store.sessions.classic?.moves?'继续上次的一局':'从 2 出发，慢慢走远。'}</p><span class="mini-grid" aria-hidden="true"><i>2</i><i>4</i><i>8</i><i>16</i></span></button></div><p class="section-label">精选玩法</p><div class="mode-grid"><button class="mode-card featured" data-mode="expedition"><span class="card-icon">✧</span><span class="tag">能力构筑</span><h3>能力远征</h3><p>九种能力，六段旅程。<br>让每一局长出自己的风格。</p></button><button class="mode-card rescue" data-mode="rescue"><span class="card-icon">↶</span><span class="tag">真实败局</span><h3>败局重生</h3><p>回到那个岔路口。<br>给走到尽头的棋盘一次转机。</p></button></div><p class="section-label">换一种节奏</p><div class="mode-grid"><button class="mode-card compact" data-mode="daily"><h3>每日同局</h3><p>同一天，相同的起点。</p></button><button class="mode-card compact" data-mode="puzzle"><h3>谜题剧场</h3><p>十二道题，把每步想好。</p></button><button class="mode-card compact" data-mode="sprint"><h3>六十步冲刺</h3><p>有限步数，无限巧思。</p></button></div>`,'CHOOSE YOUR MOMENT');$$('[data-mode]').forEach(b=>b.onclick=()=>b.dataset.mode==='puzzle'?showLevels():b.dataset.mode==='rescue'?showRescues():switchMode(b.dataset.mode));}
async function showLevels(){await openDialog(`<h2 class="dialog-title">谜题剧场</h2><p class="dialog-intro">落子固定，答案藏在几步之间。独立以最短路线完成，点亮三颗星。</p><div class="level-grid">${levels.map(l=>`<button class="level" data-level="${l.id}"><b>${String(l.id+1).padStart(2,'0')}</b><span>${esc(l.title)}</span><small>${'★'.repeat(store.meta.stars[l.id]||0)}${'☆'.repeat(3-(store.meta.stars[l.id]||0))}</small></button>`).join('')}</div>${store.sessions.puzzle?'<button class="text-button" id="continue-puzzle">继续上次的谜题 →</button>':''}`,'TWELVE LITTLE STORIES');$$('[data-level]').forEach(b=>b.onclick=()=>switchMode('puzzle',levels[Number(b.dataset.level)],true));if($('#continue-puzzle'))$('#continue-puzzle').onclick=()=>switchMode('puzzle');}
async function showDraft(){if(!['draft','clear'].includes(status(game)))return;const offers=game.extra.offers.slice();await openDialog(`<h2 class="dialog-title">${game.extra.stage===0&&game.extra.phase==='draft'?'从这里，长出风格。':'带一点新可能上路。'}</h2><p class="dialog-intro">选择一张能力卡。已拥有的能力会升级，效果延续到旅程结束。</p><div class="ability-list">${offers.map(k=>`<button class="ability" data-perk="${k}"><span>${ABILITIES[k][2]}</span><div><h3>${ABILITIES[k][0]} <small>${game.extra.perks[k]?'升级 · II':'解锁 · I'}</small></h3><p>${ABILITIES[k][1]}</p></div></button>`).join('')}</div><p class="fine-print">每过一关，保留大数字并移除一枚最小方块。下一关开始后，上一关的撤销记录将收起。</p>`,'CHOOSE ONE');$$('[data-perk]').forEach(b=>b.onclick=()=>{if(choose(game,b.dataset.perk)){version++;analysis=null;closeDialog();renderTiles();render();persist();toast(`已获得 ${ABILITIES[b.dataset.perk][0]}`);}});}
async function showPerks(){const e=game.extra;await openDialog(`<h2 class="dialog-title">你的能力组合</h2><p class="dialog-intro">第 ${e.stage+1} / 6 关 · 能量 ${e.energy} / 12</p><div class="ability-list">${Object.entries(e.perks).map(([k,r])=>`<div class="ability"><span>${ABILITIES[k][2]}</span><div><h3>${ABILITIES[k][0]} <small>${r===2?'II':'I'}</small></h3><p>${ABILITIES[k][1]}</p></div></div>`).join('')||'<p class="fine-print">先选择第一张能力卡。</p>'}</div><p class="fine-print">凝时：消耗 5 能量，阻止 ${2+(e.perks.ice||0)} 次落子，冷却六步。<br>交换：消耗 ${swapCost(e)} 能量，交换两枚不同数字。<br>主动能力不消耗移动步数，也可以撤销。</p>`,'YOUR BUILD');}
function allRescues(){return [...store.meta.rescues,...practice];}
function currentChallenge(){return allRescues().find(c=>c.id===game.extra.challenge);}
async function showRescues(){await openDialog(`<h2 class="dialog-title">再给棋盘一次机会。</h2><p class="dialog-intro">在真实败局前回退几步，找到另一条路。六步之内打开三格空间，即为破局。</p>${store.sessions.rescue?'<button class="primary" id="continue-rescue">继续上次的挑战 →</button>':''}<p class="section-label">${store.meta.rescues.length?'我的转机':'你的转机，会在这里留下。'}</p>${store.meta.rescues.length?`<div class="menu-list">${store.meta.rescues.map(c=>`<button data-rescue="${esc(c.id)}">${esc(c.title)} <span>${c.source_score.toLocaleString()} 分 · 回退 ${c.rewind} 步</span></button>`).join('')}</div>`:'<p class="dialog-intro">经典、每日或冲刺中棋盘满了之后，点「寻找转机」。只收录经过验证、有解的局面。</p>'}<p class="section-label">先用这些真实局面练练手</p><div class="menu-list">${practice.map(c=>`<button data-rescue="${esc(c.id)}">${esc(c.title)} <span>参考 ${c.par} 步 →</span></button>`).join('')}</div>`,'A SECOND CHANCE');$$('[data-rescue]').forEach(b=>b.onclick=()=>switchMode('rescue',allRescues().find(c=>c.id===b.dataset.rescue),true));if($('#continue-rescue'))$('#continue-rescue').onclick=()=>switchMode('rescue');}
async function extractChallenge(){await settle();$('#extract-rescue').disabled=true;$('#extract-rescue').textContent='正在寻找…';const id=game.id;try{const r=await compute('extract');if(game.id!==id)return;if(r.status==='found'){const pinned=store.sessions.rescue?.extra.challenge,old=store.meta.rescues.filter(c=>c.id!==r.challenge.id);const pin=old.find(c=>c.id===pinned);store.meta.rescues=[r.challenge,...(pin?[pin]:[]),...old.filter(c=>c.id!==pinned)].slice(0,6);persist();await switchMode('rescue',r.challenge,true);toast('找到一条经过验证的转机。原局已保留。');}else{toast(r.status==='timeout'?'搜索时间已用完，暂时没有找到验证路线。':'最近十步里没有找到符合条件的转机。');render();}}catch(e){if(e.name!=='AbortError'){toast(e.message);render();}}}
async function restart(){const mode=game.mode,data=mode==='puzzle'?game.extra.level:mode==='rescue'?currentChallenge():null;if(status(game)==='play'&&game.moves>0){await openDialog('<h2 class="dialog-title">重新开始这一局？</h2><p class="dialog-intro">当前棋盘将被替换，已经取得的最佳成绩会保留。</p><div class="button-row"><button class="primary" id="confirm-restart">重新开始</button><button class="secondary" id="cancel-restart">继续这一局</button></div>');$('#confirm-restart').onclick=()=>switchMode(mode,data,true);$('#cancel-restart').onclick=closeDialog;}else await switchMode(mode,data,true);}
function miniBoard(board){return `<div class="mini-board" aria-label="复盘棋盘">${board.map(v=>`<i>${v||''}</i>`).join('')}</div>`;}
async function showReview(route='mine'){
  const challenge=game.mode==='rescue'?currentChallenge():null;if(route==='reference'&&status(game)!=='won'){game.assisted=true;persist();render();}
  let frames,title;if(route==='original'&&challenge){frames=[{board:challenge.origin.board,caption:`回退 ${challenge.rewind} 步的起点`},...challenge.original.map((f,i)=>({board:f.board,caption:`原局第 ${i+1} 步 · ${directions[f.direction]||'移动'}`}))];title='当时走过的路';}
  else if(route==='reference'&&challenge){let b=challenge.origin.board.slice(),rng=new Random(0,challenge.origin.rng);frames=[{board:b,caption:'参考路线起点'}];for(const d of challenge.solution){b=slide(b,d).board;spawn(b,rng);frames.push({board:b.slice(),caption:`${directions[d]} · 空格 ${empty(b)}`});}title='另一种可能';}
  else{frames=[...game.history,snapshot(game)].map(f=>({board:f.board,caption:`${f.moves} 步 · ${f.score.toLocaleString()} 分`}));title='你走过的每一步';}
  let index=frames.length-1;await openDialog(`<h2 class="dialog-title">${title}</h2><p class="dialog-intro">${challenge?'看看转机发生在哪一步。':'最近一百次操作，随时回看。复盘不会改变当前棋盘。'}</p>${challenge?`<div class="route-tabs"><button data-route="mine" class="${route==='mine'?'active':''}">我的路线</button><button data-route="original" class="${route==='original'?'active':''}">原局路线</button><button data-route="reference" class="${route==='reference'?'active':''}">参考路线</button></div>`:''}<div id="review-board"></div><p class="review-caption" id="review-caption"></p><div class="review-controls"><button id="frame-prev" aria-label="上一步">←</button><span id="frame-index"></span><button id="frame-next" aria-label="下一步">→</button></div>${challenge&&status(game)!=='won'?'<p class="fine-print">提前查看参考路线会将这次挑战标为辅助探索。</p>':''}`,'THE REPLAY');
  const update=()=>{$('#review-board').innerHTML=miniBoard(frames[index].board);$('#review-caption').textContent=frames[index].caption;$('#frame-index').textContent=`${index+1} / ${frames.length}`;$('#frame-prev').disabled=index===0;$('#frame-next').disabled=index===frames.length-1;};$('#frame-prev').onclick=()=>{index=Math.max(0,index-1);update();};$('#frame-next').onclick=()=>{index=Math.min(frames.length-1,index+1);update();};$$('[data-route]').forEach(b=>b.onclick=()=>showReview(b.dataset.route));update();
}
async function showRecords(){await openDialog(`<h2 class="dialog-title">留下的成绩</h2><p class="dialog-intro">手动与辅助探索分别记录。所有成绩只存在这台设备上。</p>${store.meta.records.length?store.meta.records.slice(0,30).map(r=>`<div class="record-row"><div>${names[r.mode]||'2048'}<br><small>${esc(r.date.slice(0,10))} · ${r.assisted?'辅助':'手动'}${r.won?' · 达成':''}</small></div><div>${Number(r.score).toLocaleString()}<br><small>最大 ${Number(r.tile)}</small></div></div>`).join(''):'<p class="fine-print">完成第一局，成绩就会出现在这里。</p>'}`,'YOUR MOMENTS');}
async function showMore(){await openDialog(`<h2 class="dialog-title">这一局，慢慢来。</h2><div class="menu-list"><button id="menu-restart">重新开始<span>最佳成绩保留 ↗</span></button><button id="menu-redo" ${game.future.length?'':'disabled'}>重做<span>${game.future.length} 步可恢复</span></button><button id="menu-review">回看这一局<span>最近 ${game.history.length} 步 →</span></button><button id="menu-records">我的成绩<span>手动 / 辅助 →</span></button><button id="menu-modes">切换玩法<span>六种节奏 →</span></button><button id="menu-help">操作与安装<span>添加到主屏幕 →</span></button></div>`);$('#menu-restart').onclick=restart;$('#menu-redo').onclick=()=>{if(redo(game)){version++;analysis=null;persist();closeDialog();renderTiles();render();}};$('#menu-review').onclick=()=>showReview();$('#menu-records').onclick=showRecords;$('#menu-modes').onclick=showModes;$('#menu-help').onclick=showHelp;}
async function showHelp(){await openDialog('<h2 class="dialog-title">放进你的日常。</h2><p class="dialog-intro">在 iPhone 或 iPad 的 Safari 中打开游戏，点分享按钮，再选择「添加到主屏幕」。首次完整打开后，可离线游玩。</p><div class="setting-row"><div>滑动，或者轻点<p>在棋盘内向四个方向滑动，也可使用下方方向按钮。键盘支持方向键与 WASD。</p></div></div><div class="setting-row"><div>随时离开，下次继续<p>六种玩法各自保存进度。自动玩在切到后台、打开菜单时暂停。</p></div></div><div class="setting-row"><div>把进度带去另一台设备<p>在设置里导出备份，再在另一台设备导入。手机、平板和 Safari 主屏幕应用可能使用各自的存储空间。</p></div></div><p class="fine-print">建议使用 iOS / iPadOS 16.4 或更新版本。隐私浏览或清理网站数据可能清除存档，请定期导出备份。电脑版存档与触屏版分别保存。</p>','MADE FOR YOUR HANDS');}
async function showSettings(){const s=store.meta.settings;await openDialog(`<h2 class="dialog-title">舒服，就这样玩。</h2><label class="setting-row"><div>轻声反馈<p>合并时，一点恰到好处的声音。</p></div><input id="setting-sound" type="checkbox" ${s.sound?'checked':''}></label><label class="setting-row"><div>灵动效果<p>${reduced.matches?'系统已开启减少动态效果。':'平滑位移、轻盈的合并回弹。'}</p></div><input id="setting-motion" type="checkbox" ${s.motion?'checked':''}></label><label class="setting-row">外观<select id="setting-theme"><option value="light">晨雾</option><option value="dark">夜色</option><option value="system">跟随系统</option></select></label><label class="setting-row">思考深度<select id="setting-strength"><option value="quick">轻快</option><option value="balanced">均衡</option><option value="deep">深思</option></select></label><label class="setting-row">自动玩节奏<select id="setting-pace"><option value="calm">从容</option><option value="quick">利落</option></select></label><p class="section-label">存档与设备</p><div class="menu-list"><button id="export-save">导出进度<span>保存到文件 →</span></button><button id="import-save">导入进度<span>从触屏版备份恢复 →</span></button><button id="install-help">添加到主屏幕<span>iPhone / iPad →</span></button></div><p class="fine-print">智能助手使用概率搜索；谜题与重生挑战使用精确路线搜索。开启提示或自动玩后，本局记为辅助探索。</p>`,'MAKE IT YOURS');
  for(const key of ['sound','motion','theme','strength','pace']){const el=$(`#setting-${key}`);if(el.tagName==='SELECT')el.value=s[key];el.onchange=()=>{store.meta.settings[key]=el.type==='checkbox'?el.checked:el.value;applySettings();persist();if(key==='sound'&&el.checked)sound(8);};}
  $('#export-save').onclick=exportSave;$('#import-save').onclick=showImport;$('#install-help').onclick=showHelp;
}
function exportSave(){persist();const blob=new Blob([store.export()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Lumina-${localDate()}-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('备份已准备好，请保存到「文件」。');}
async function showImport(){await openDialog('<h2 class="dialog-title">恢复另一份进度</h2><p class="dialog-intro">导入会替换此设备当前的触屏版进度。建议先导出当前存档留作备份。</p><div class="button-row"><button id="backup-first" class="secondary">先导出备份</button><button id="select-backup" class="primary">选择备份文件</button></div><input id="backup-file" type="file" accept=".json,application/json" hidden>');$('#backup-first').onclick=exportSave;$('#select-backup').onclick=()=>$('#backup-file').click();$('#backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000000)throw new Error('备份文件过大');await store.import(await file.text());game=clone(store.sessions.classic||newGame('classic',freshSeed()));applySettings();version++;analysis=null;closeDialog();renderTiles();render();persist();toast('进度已恢复。');}catch(error){toast(error.message||'备份无法读取');}};}

$('#modes').onclick=showModes;$('#featured').onclick=showModes;$('#settings').onclick=showSettings;$('#more').onclick=showMore;$('#hint').onclick=hint;$('#auto').onclick=toggleAuto;$('#undo').onclick=async()=>{await settle();if(undo(game)){version++;analysis=null;swapping=false;swapSelection=null;persist();renderTiles();render();announce('已撤销上一步');}};
$$('[data-dir]').forEach(b=>b.onclick=()=>input(b.dataset.dir));
let gesture=null;$('#board').addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0||$('#dialog').open)return;gesture={x:e.clientX,y:e.clientY,id:e.pointerId};try{$('#board').setPointerCapture(e.pointerId);}catch{}});
$('#board').addEventListener('pointerup',e=>{if(!gesture||e.pointerId!==gesture.id)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;gesture=null;
  if(Math.max(Math.abs(dx),Math.abs(dy))<18){if(swapping&&!busy){const r=$('.tiles').getBoundingClientRect(),gap=parseFloat(getComputedStyle($('.cells')).columnGap),step=(r.width+gap)/4,x=e.clientX-r.left,y=e.clientY-r.top;if(x<0||y<0||x>=r.width||y>=r.height||x%step>step-gap||y%step>step-gap)return;const i=Math.floor(y/step)*4+Math.floor(x/step);if(!game.board[i])return;if(swapSelection===null){swapSelection=i;renderTiles();}else if(swapSelection===i){swapSelection=null;renderTiles();}else if(game.board[swapSelection]!==game.board[i])input(`swap:${Math.min(swapSelection,i)}:${Math.max(swapSelection,i)}`);else toast('请选择两枚不同的数字');}return;}
  input(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'down':'up');
});$('#board').addEventListener('pointercancel',()=>gesture=null);$('#board').addEventListener('lostpointercapture',()=>gesture=null);$('#board').addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',e=>{if(!game||$('#dialog').open||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||e.metaKey||e.ctrlKey||e.altKey)return;const d={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',a:'left',d:'right',w:'up',s:'down'}[e.key];if(d){e.preventDefault();if(!e.repeat)input(d);}});
window.addEventListener('resize',()=>{activeAnimations.forEach(a=>{try{a.finish();}catch{}});});document.addEventListener('visibilitychange',()=>{if(document.hidden){queued=[];stopAuto();if(game){persist();render();}audioContext?.suspend().catch(()=>{});}});window.addEventListener('pagehide',()=>{if(game&&!remoteLock)store.emergency(game);});
const tabID=Math.random().toString(36).slice(2);let channel=null;try{channel=new BroadcastChannel('lumina-active-game');channel.onmessage=async({data})=>{if(data.source===tabID||!game||remoteLock)return;remoteLock=true;await settle();await openDialog('<h2 class="dialog-title">这一局在别处继续了。</h2><p class="dialog-intro">另一个窗口更新了同一局。重新载入最新进度后继续，避免覆盖。</p><button class="primary" id="reload-current">载入最新进度</button>');$('#reload-current').onclick=()=>location.reload();};}catch{}

async function registerWebMCP(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController(),read=()=>({mode:game.mode,board:game.board.slice(),score:game.score,moves:game.moves,status:status(game),remaining:Number.isFinite(remaining(game))?remaining(game):null,assisted:game.assisted});
  const tools=[{name:'read_game_state',title:'读取当前棋盘',description:'读取 LUMINA 当前棋盘、分数、玩法和状态，不改变游戏。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(input&&Object.keys(input).length)throw new Error('No arguments accepted');return read();}},
    {name:'make_game_move',title:'移动当前棋盘',description:'向指定方向移动当前棋盘一次，并将本局标记为辅助探索。遵循同一套游戏规则与动画。',inputSchema:{type:'object',properties:{direction:{type:'string',enum:DIRS}},required:['direction'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!DIRS.includes(input.direction)||Object.keys(input).some(k=>k!=='direction'))throw new Error('Invalid direction');if(busy||$('#dialog').open||remoteLock)throw new Error('Game is busy or a menu is open');stopAuto();const changed=await play(input.direction,true);return {...read(),changed};}},
    {name:'open_game_modes',title:'打开玩法选择',description:'打开玩法选择菜单，暂停自动玩；保留当前棋盘。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(input&&Object.keys(input).length)throw new Error('No arguments accepted');await showModes();return {menu:'modes',modes:Object.keys(names)};}}];
  for(const tool of tools)try{await document.modelContext.registerTool(tool,{signal:lifecycle.signal});}catch(e){console.warn('Game tool unavailable',e.message);}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
async function init(){try{const [l,p]=await Promise.all(['./puzzle-levels.json','./rescue-practice.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw new Error('玩法文件未能加载');return r.json();}));levels=l;practice=p;store.practiceIDs=p.map(c=>c.id);await store.open();game=clone(store.sessions.classic||newGame('classic',freshSeed()));applySettings();$$('.app button').forEach(b=>b.disabled=false);renderTiles();render();persist();registerWebMCP();
  if('serviceWorker' in navigator&&!['127.0.0.1','localhost'].includes(location.hostname))navigator.serviceWorker.register('./sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const installing=reg.installing;installing?.addEventListener('statechange',()=>{if(installing.state==='installed'&&navigator.serviceWorker.controller)toast('新版已准备好，下次重新打开时更新。');});});}).catch(()=>toast('离线准备未完成，联网时仍可正常游玩。'));
}catch(e){$('#board-message').hidden=false;$('#board-message').innerHTML='<h2>差一点就准备好了。</h2><p>游戏文件未能完整加载，请联网后重试。</p><button class="primary" id="retry-load">重新载入</button>';$('#retry-load').onclick=()=>location.reload();console.error(e);}}
init();
